-- FINAGRO Web — Fluxo de Caixa por vencimento, saldos e isolamento tenant.
begin;
create schema test_cf;
create function test_cf.ok(c boolean,m text) returns void language plpgsql set search_path='' as $$begin if c is not true then raise exception 'TEST FAILED: %',m;end if;end$$;
create function test_cf.err(q text,e text) returns void language plpgsql set search_path='' as $$declare m text;begin begin execute q;exception when others then m=sqlerrm;if position(e in m)=0 then raise exception 'TEST FAILED expected %, got %',e,m;end if;return;end;raise exception 'TEST FAILED expected %',e;end$$;
create function test_cf.v(j jsonb,c text,m text) returns numeric language sql immutable set search_path='' as $$select coalesce((x->'values'->>$3)::numeric,0) from jsonb_array_elements($1->'lines')x where x->>'code'=$2$$;
grant usage on schema test_cf to authenticated;grant execute on all functions in schema test_cf to authenticated;
select private.seed_default_roles('e1000000-0000-0000-0000-000000000010','e1000000-0000-0000-0000-000000000001');select private.seed_default_roles('f1000000-0000-0000-0000-000000000020','f1000000-0000-0000-0000-000000000001');
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','e1000000-0000-0000-0000-000000000001',true);
select public.apply_chart_account_template('e1000000-0000-0000-0000-000000000010','3269e51b-12de-5887-a85c-4461af91b4e9');select public.apply_reporting_template('e1000000-0000-0000-0000-000000000010','b71768e2-a0ef-5b02-b7d5-ea900bed4104');reset role;
create temporary table ac as select code,id from public.chart_accounts where organization_id='e1000000-0000-0000-0000-000000000010';
update public.chart_accounts set allows_allocation=true where id=(select id from ac where code='FINAGRO-V1-G002-S001');
update public.allocation_rule_items set percentage=50 where allocation_rule_id='e1000000-0000-0000-0000-000000000301';set constraints all immediate;set constraints all deferred;
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','e1000000-0000-0000-0000-000000000001',true);
create temporary table r as select public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01')j;
select test_cf.ok(test_cf.v((select j from r),'DFC_PREVISTO.FINAGRO-V1-G020-S001','2027-01-01')=100,'due date controls month; issue and settlement dates do not');
select test_cf.ok(test_cf.v((select j from r),'DFC_PREVISTO.FINAGRO-V1-G002-S001','2027-02-01')=10.01,'scheduled expense and numeric cents are included');
select test_cf.ok(test_cf.v((select j from r),'DFC_PREVISTO.FINAGRO-V1-G012-S001','2027-01-01')=200 and test_cf.v((select j from r),'DFC_PREVISTO.FINAGRO-V1-G011-S001','2027-02-01')=50 and test_cf.v((select j from r),'DFC_PREVISTO.FINAGRO-V1-G011-S002','2027-02-01')=5,'financing entry, principal and interest remain separate');
select test_cf.ok(test_cf.v((select j from r),'DFC_PREVISTO.CALC.TOTAL_ENTRADAS','2027-01-01')=300 and test_cf.v((select j from r),'DFC_PREVISTO.CALC.TOTAL_SAIDAS','2027-02-01')=65.01,'configured directions calculate flows without treating opening balance as revenue');
select test_cf.ok(test_cf.v((select j from r),'DFC_PREVISTO.CALC.SALDO_INICIAL_MENSAL','2027-01-01')=1000 and test_cf.v((select j from r),'DFC_PREVISTO.CALC.SALDO_CAIXA_ACUMULADO','2027-01-01')=1300 and test_cf.v((select j from r),'DFC_PREVISTO.CALC.SALDO_INICIAL_MENSAL','2027-02-01')=1300 and test_cf.v((select j from r),'DFC_PREVISTO.CALC.SALDO_CAIXA_ACUMULADO','2027-02-01')=1234.99,'opening and closing balances roll forward deterministically');
select test_cf.ok((select (x->>'total')::numeric from r cross join lateral jsonb_array_elements(j->'lines') x where x->>'code'='DFC_PREVISTO.CALC.SALDO_INICIAL_MENSAL')=1000 and (select (x->>'total')::numeric from r cross join lateral jsonb_array_elements(j->'lines') x where x->>'code'='DFC_PREVISTO.CALC.SALDO_CAIXA_ACUMULADO')=1234.99,'balance totals represent first opening and final closing rather than summing monthly balances');
select test_cf.ok(((select j from r)->'coverage'->>'entries_unmapped')::int=2 and ((select j from r)->'coverage'->>'unclassified_amount')::numeric=10.33,'transfers and non-operational entry remain visible and unmapped');
select test_cf.ok(test_cf.v(public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01','e1000000-0000-0000-0000-000000000101'),'DFC_PREVISTO.FINAGRO-V1-G002-S001','2027-02-01')=4.50,'farm uses stored allocation snapshot');
select test_cf.ok(test_cf.v(public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01','e1000000-0000-0000-0000-000000000101'),'DFC_PREVISTO.FINAGRO-V1-G002-S001','2027-02-01')+test_cf.v(public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01','e1000000-0000-0000-0000-000000000102'),'DFC_PREVISTO.FINAGRO-V1-G002-S001','2027-02-01')=10.01,'farms reconcile to consolidated after allocation rule changes');
select test_cf.ok(position('account.name' in pg_get_functiondef('public.get_realized_cash_flow(uuid,date,date,uuid,uuid)'::regprocedure))=0 and position('source_name' in pg_get_functiondef('public.get_realized_cash_flow(uuid,date,date,uuid,uuid)'::regprocedure))=0 and position('settlements' in pg_get_functiondef('public.get_realized_cash_flow(uuid,date,date,uuid,uuid)'::regprocedure))=0 and position('installment_plans' in pg_get_functiondef('public.get_realized_cash_flow(uuid,date,date,uuid,uuid)'::regprocedure))=0 and position(' limit ' in lower(pg_get_functiondef('public.get_realized_cash_flow(uuid,date,date,uuid,uuid)'::regprocedure)))=0,'engine is name-, settlement-, installment-plan- and pagination-independent');
select test_cf.err($$select public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01','f1000000-0000-0000-0000-000000000101')$$,'FARM_NOT_FOUND_IN_ORGANIZATION');
select test_cf.err($$select public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01',null,'f1000000-0000-0000-0000-000000000999')$$,'CASH_FLOW_STRUCTURE_NOT_FOUND');
select set_config('request.jwt.claim.sub','e1000000-0000-0000-0000-000000000002',true);select test_cf.ok((public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01')->>'structure_id') is not null,'READ_ONLY can query');
select set_config('request.jwt.claim.sub','f1000000-0000-0000-0000-000000000001',true);select test_cf.err($$select public.get_realized_cash_flow('e1000000-0000-0000-0000-000000000010','2027-01-01','2027-02-01')$$,'PERMISSION_DENIED');
reset role;rollback;
